package pe.edu.upc.ice.track.platform.monitoring.domain.model.aggregates;

import lombok.Getter;
import pe.edu.upc.ice.track.platform.monitoring.domain.model.valueobjects.EdgeEventResult;
import pe.edu.upc.ice.track.platform.monitoring.domain.model.valueobjects.EdgeEventType;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

/**
 * EdgeEvent aggregate root of the {@code monitoring} bounded context.
 *
 * <p>The record that an event reported by an edge gateway was processed, and what it did. Its
 * {@code eventUid} is generated by the gateway and unique across the platform, which is what makes
 * event delivery idempotent: a gateway retries an event until it is acknowledged, and a retry of an
 * event already recorded is answered with the stored record instead of being processed again. The
 * record is written in the same transaction as the alert or maintenance window it changed.</p>
 */
@Getter
public class EdgeEvent {

  private final Long id;
  private final UUID eventUid;
  private final Long deviceId;
  private final Long equipmentId;
  private final EdgeEventType type;
  private final Instant occurredAt;
  private final Double temperatureCelsius;
  private final Double peakTemperatureCelsius;
  private final EdgeEventResult result;
  private final Long alertId;
  private final Long maintenanceWindowId;

  /**
   * @param id                     the persistence identity, or {@code null} when not yet persisted
   * @param eventUid               the identifier the gateway generated; required
   * @param deviceId               the device that reported the event; required
   * @param equipmentId            the unit the device is paired with; required
   * @param type                   the kind of event; required
   * @param occurredAt             when the gateway observed it; required
   * @param temperatureCelsius     the temperature reported with a detection, or {@code null}
   * @param peakTemperatureCelsius the peak reported with a normalization, or {@code null}
   * @param result                 what processing the event did; required
   * @param alertId                the alert opened, already active or resolved, or {@code null}
   * @param maintenanceWindowId    the maintenance window opened, kept, promoted, closed or covering
   *                               a suppressed detection, or {@code null}
   */
  public EdgeEvent(Long id, UUID eventUid, Long deviceId, Long equipmentId, EdgeEventType type,
                   Instant occurredAt, Double temperatureCelsius, Double peakTemperatureCelsius,
                   EdgeEventResult result, Long alertId, Long maintenanceWindowId) {
    this.id = id;
    this.eventUid = Objects.requireNonNull(eventUid, "eventUid must not be null");
    this.deviceId = Objects.requireNonNull(deviceId, "deviceId must not be null");
    this.equipmentId = Objects.requireNonNull(equipmentId, "equipmentId must not be null");
    this.type = Objects.requireNonNull(type, "type must not be null");
    this.occurredAt = Objects.requireNonNull(occurredAt, "occurredAt must not be null");
    this.temperatureCelsius = temperatureCelsius;
    this.peakTemperatureCelsius = peakTemperatureCelsius;
    this.result = Objects.requireNonNull(result, "result must not be null");
    this.alertId = alertId;
    this.maintenanceWindowId = maintenanceWindowId;
  }
}
